const commonFeedback = (evidence, strategy) => ({
  correct: { es: `Correcto. La evidencia dice: “${evidence}”`, en: `Correct. The evidence says: “${evidence}”` },
  incorrect: { es: 'Vuelve al fragmento indicado y separa la idea principal de los detalles.', en: 'Return to the relevant part and separate the main idea from the details.' },
  strategy: { es: strategy, en: strategy },
})

const q = (type, skill, prompt, options, answer, evidence, strategy = 'Busca palabras clave y comprueba la relación con la pregunta.') => ({
  type, skill, prompt, options, answer, evidence, feedback: commonFeedback(evidence, strategy), maxAttempts: type === 'ordering' ? 3 : 2,
})

